"""Habit details page: why people open one habit's own page (Current Work 133, 19 Oct 2026). Habit apps only.
Written by Claude (Claude Code). habit_details_scan.py screened 932,330 reviews in the App Store and Play Store corpora
(to-do apps left out) and matched 2,018 habit-app reviews about a habit's own page, its history, calendar, stats,
streaks, milestones, notes, editing past days or its settings. All 2,018 were read by hand; 1,647 are on topic (below).
The other 371 matched a keyword but were about something else (Today, widgets, reminders, sync, prices); Hevy, a workout
log, was left uncoded. Run from Research/:
  python3 -I "Research Reports/Day Structure and Organization/Habit Details Evidence/habit_details_classification.py"
"""
import html, json, os, re

CODEBOOK = {
 "CAL_MONTH": "wants, uses or praises a month calendar of one habit (which days it was done)",
 "CAL_YEAR": "wants, uses or praises a year view of one habit (heat map, year in pixels, GitHub-style grid)",
 "HISTORY_LONG": "wants to look back over a habit's whole history (months and years), or praises it",
 "COUNT_DAYS": "wants to see how many days it was done in a month or period, not only a streak",
 "LAST_DONE": "opens the habit to see when it was last done",
 "AMOUNT_ON_CAL": "wants the amount (or time) written on each day of the calendar",
 "PARTIAL": "wants a part-done day shown as part done, not as a miss",
 "SKIP_DISTINCT": "wants skipped, missed and done days to look different (or not-done marked), or praises it",
 "NODATA_DISTINCT": "a day with nothing logged looks the same as a day marked not done",
 "LOGS_IN_DAY": "wants to see a day's own logs or which habits were done that day",
 "PLAN_AHEAD": "wants to see the days a habit is planned for ahead",
 "NOTES_ADD": "wants to write a note on a habit's day (what was done, how it went), or praises it",
 "NOTES_READ": "wants to read past notes back: all of a habit's notes, from the calendar, without editing them",
 "NOTE_ON_MISS": "wants a note on a day the habit wasn't done (why it was missed)",
 "SLIP_NOTE": "writes a note on a slip of a quit habit",
 "NOTES_EDIT": "can't edit or copy a note once written",
 "FIX_PAST": "wants to mark or correct a past day, or praises being able to",
 "BACKFILL_PRESTART": "wants to log days before the habit was added (an existing streak, another app's data)",
 "FIX_SAFE": "a correction should be safe: undo a mistaken mark, confirm before changing, no accidental resets",
 "ACCIDENTAL_EDIT": "past days changed by accident from the page, or wants past days locked",
 "STREAK_SEE": "opens the habit for its current streak or best streak, or praises seeing them",
 "RUNS_LIST": "wants best and past streaks listed, not just the current one",
 "PER_HABIT_STATS": "wants, uses or praises statistics and charts for one habit (rate, graphs, trend)",
 "TOTALS": "wants totals (how many times, how much in all) for a habit",
 "SUMMARY_PERIOD": "wants the habit's week, month or year summed up",
 "CONSISTENCY_OVER_STREAK": "a score or completion rate that forgives a missed day matters more than the streak",
 "QUIT_STATS": "a quit habit's own numbers: time since, longest run, money or time saved",
 "STREAK_FREEZE": "wants a missed day not to break the streak (freeze, grace day), or praises it",
 "STREAK_FREEZE_NEG": "dislikes streak freezes",
 "STATS_WEAK": "the habit's statistics are too thin to be useful",
 "COMPARE": "wants to compare two habits or periods",
 "PATTERNS": "looks for patterns: which weekdays, what got in the way, cause and effect",
 "MILESTONE": "wants or enjoys milestones, badges or achievements for a habit",
 "MILESTONE_NEG": "milestones felt pointless, nagging or broken",
 "EDIT_SETTINGS": "opens the habit to change its settings (name, goal, schedule, reminders, colour)",
 "EDIT_KEEPS_HISTORY": "changing a habit's goal, time or schedule must not wipe or rewrite its past",
 "READ_ABOUT": "wants the habit's description, why or how-to visible on its page",
 "CUSTOM_PAGE": "praises a habit page they can add their own cards to (journal, counters, photos)",
 "STATS_WRONG": "the habit's streak, count or calendar is wrong",
 "HISTORY_KEEP": "a habit's history was lost (update, sync, archive, delete) or must be kept",
 "STATS_CONFUSING": "the habit's numbers are hard to understand (percentages, future days counted)",
 "CAL_CONFUSING": "the habit's calendar is hard to read (no dates, tiny, colours, unclear marks)",
 "SLOW_PAGE": "the habit's page is slow, crashes or shows nothing when opened",
 "STREAK_ON_LIST": "wants the streak on the list or widget so they don't have to open the habit",
 "ALL_OVERVIEW": "wants one view of all habits together instead of opening each",
 "LOG_ON_PAGE": "wants to log from the habit's page (a reminder or tap opened the page and logging wasn't there)",
 "NAV_HARD": "getting to or around the habit's page takes too many taps, scrolls or swipes",
 "OPEN_TO_SEE": "says why they open the habit, or what tapping a habit should show first",
 "CLUTTER": "the habit's page or its pieces are cluttered or in the way",
 "NONDAILY_VIEW": "a weekly or monthly goal is shown or counted as if it were daily",
 "EXPORT": "wants the habit's history exported or backed up",
 "STATS_HIDE": "wants to hide the streak or numbers",
 "PAGE_PRAISE": "praises the habit's page as a whole",
 "SHARE": "wants to share the habit's progress",
 "RATE": "wants to rate a day, not only tick it",
 "CLUTTER_WARN": "warns a habit page can get cluttered",
 "FIND_HABIT": "wants to find a habit quickly",
}

